#!/bin/sh
# Generated by the Open Box Drive setup page. Installs the native messaging host for ___BROWSER___.
set -e

APPLICATION_NAME="___APPLICATIONNAME___"
DEST_DIR="$HOME/Library/Application Support/OpenBoxDrive"
if [ "___BROWSER___" = "edge" ]; then
    HOSTS_DIR="$HOME/Library/Application Support/Microsoft Edge/NativeMessagingHosts"
else
    HOSTS_DIR="$HOME/Library/Application Support/Google/Chrome/NativeMessagingHosts"
fi

mkdir -p "$DEST_DIR"
cat > "$DEST_DIR/native-messaging-host-app.py" <<'OPEN_BOX_DRIVE_EOF'
___HOST_PY___
OPEN_BOX_DRIVE_EOF
cat > "$DEST_DIR/native-messaging-host-app.sh" <<'OPEN_BOX_DRIVE_EOF'
___HOST_SH___
OPEN_BOX_DRIVE_EOF
chmod +x "$DEST_DIR/native-messaging-host-app.sh"

# The browser does not create this folder until some native host is installed
mkdir -p "$HOSTS_DIR"
cat > "$HOSTS_DIR/$APPLICATION_NAME.json" <<OPEN_BOX_DRIVE_EOF
___MANIFEST___
OPEN_BOX_DRIVE_EOF

echo "Open Box Drive: setup finished. Go back to the browser."
